/* Translate only after the document has been parsed, then reveal it. */
function translateAimeePage(){
(()=>{const t=window.aimeeT;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('script,style'))continue;const key=node.nodeValue.trim();if(key)node.nodeValue=node.nodeValue.replace(key,t(key));}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr))el.setAttribute(attr,t(el.getAttribute(attr)));});document.title=t(document.title);document.documentElement.setAttribute('data-language-ready','');})();
}
